ValidationRule.errorConditionFormula:
OR(

    /* 1. GST is mandatory when Case/Opportunity is tagged and not exempted */
    AND(
        ISBLANK(GST_No__c),
        OR(
            AND(
                NOT(ISBLANK(Case__c)),
                NOT(ISBLANK(Account__c)),
                Account__r.GST_Exempted__c = FALSE
            ),
            AND(
                NOT(ISBLANK(Opportunity__c)),
                Opportunity__r.Gst_Exempted__c = FALSE
            )
        )
    ),

    /* 2. Existing format validation when GST is provided */
    AND(
        OR(ISNEW(), ISCHANGED(GST_No__c)),
        NOT(ISBLANK(GST_No__c)),
        NOT(
            OR(
                REGEX(GST_No__c, "^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][0-9][A-Z][0-9A-Z]$"),
                REGEX(GST_No__c, "^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][A-Z][A-Z][0-9A-Z]$")
            )
        )
    )

)
